const app = $json;
const input = $('Start Scoring Review').first().json;
const skills = Array.isArray(app.skills) ? app.skills : (typeof app.skills === 'string' ? JSON.parse(app.skills || '[]') : []);
const normalizedSkills = skills.map(s => String(s).toLowerCase());
const points = [];
if (normalizedSkills.includes('python')) points.push(20);
if (normalizedSkills.includes('fastapi') || normalizedSkills.includes('django')) points.push(15);
if (normalizedSkills.includes('sql') || normalizedSkills.includes('postgresql')) points.push(10);
if (normalizedSkills.includes('git')) points.push(5);
if (normalizedSkills.includes('rest apis') || normalizedSkills.includes('api')) points.push(10);
if (normalizedSkills.includes('docker')) points.push(10);
if (normalizedSkills.includes('aws') || normalizedSkills.includes('azure')) points.push(10);
if (normalizedSkills.includes('backend')) points.push(10);
if (Number(app.experience_years || 0) >= 3) points.push(10);
const rawScore = points.reduce((sum, value) => sum + value, 0);
const ruleScore = Math.min(100, Math.round((rawScore / 60) * 100));
const status = ruleScore >= 80 ? 'SHORTLISTED' : (ruleScore >= 60 ? 'MANUAL_REVIEW' : 'REJECTED');
const reason = status === 'SHORTLISTED' ? 'Passed rule-based shortlist threshold' : (status === 'MANUAL_REVIEW' ? 'Requires hiring-team review' : 'Below shortlist threshold');
const review = { source: 'rules-only', score: ruleScore, recommendation: status, reason, generated_at: new Date().toISOString() };
return [{ json: { application_id: app.id || input.application_id, application_code: app.application_code, correlation_id: app.correlation_id || input.correlation_id, event_id: app.event_id || input.event_id, rule_score: ruleScore, final_score: ruleScore, status, status_reason: reason, ai_review: review } }];

const scored = $('Calculate Score and Recommendation').first().json;

let analysis = $json.output ?? $json;

if (typeof analysis === 'string') {
  try {
    analysis = JSON.parse(
      analysis.replace(/```json|```/g, '').trim()
    );
  } catch {
    analysis = null;
  }
}

const validRecommendations = [
  'SHORTLISTED',
  'MANUAL_REVIEW',
  'REJECTED'
];

const valid =
  analysis &&
  typeof analysis === 'object' &&
  Number.isFinite(Number(analysis.ai_score)) &&
  validRecommendations.includes(analysis.ai_recommendation);

const aiReview = valid
  ? {
      source: 'ai-agent',
      provider_route: 'GEMINI_WITH_GROQ_FALLBACK',
      candidate_summary: analysis.candidate_summary || analysis.summary || analysis.ai_reasoning || 'AI candidate assessment completed.',
      strengths: Array.isArray(analysis.strengths)
        ? analysis.strengths
        : [],
      skill_gaps: Array.isArray(analysis.skill_gaps)
        ? analysis.skill_gaps
        : [],
      risk_flags: Array.isArray(analysis.risk_flags)
        ? analysis.risk_flags
        : [],
      ai_score: Math.max(
        0,
        Math.min(100, Math.round(Number(analysis.ai_score)))
      ),
      ai_recommendation: analysis.ai_recommendation,
      ai_reasoning: analysis.ai_reasoning || '',
      generated_at: new Date().toISOString()
    }
  : {
      source: 'rule-based-fallback',
      provider_route: 'AI_UNAVAILABLE',
      candidate_summary: '',
      strengths: [],
      skill_gaps: [],
      risk_flags: ['AI analysis was unavailable'],
      ai_score: scored.rule_score,
      ai_recommendation: scored.status,
      ai_reasoning: scored.status_reason,
      generated_at: new Date().toISOString()
    };

return [{
  json: {
    ...scored,
    ai_review: aiReview,
    ai_analysis_status: valid
      ? 'COMPLETED'
      : 'RULE_BASED_FALLBACK'
  }
}];

const scoring = $('Return Scoring Result').first().json;
const interview = $json;

return [{
  json: {
    ...scoring,
    ...interview,
    ai_analysis_status: scoring.ai_analysis_status,
    ai_review: scoring.ai_review,
    review_source: scoring.review_source
  }
}];
